// Isolated browser verification using a fixture generated by planOctober, never production writes.
// node tests/card-statement-dates-browser-validation.cjs [playwright module] [base URL] [fixture JSON]
const { chromium } = require(process.argv[2] || 'playwright');
const assert = require('node:assert/strict');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const { tmpdir } = require('node:os');

(async () => {
  const fixture = JSON.parse(readFileSync(process.argv[4], 'utf8'));
  const original = JSON.stringify(fixture);
  const base = process.argv[3] || 'http://127.0.0.1:3100';
  const browser = await chromium.launch({ channel: 'msedge', headless: true });
  try {
    const context = await browser.newContext({ viewport: { width: 1440, height: 900 }, extraHTTPHeaders: { Origin: base } });
    const marker = await context.request.get(base + '/api/auth/session');
    assert.equal(marker.headers()['x-contas-tatu-isolated'], 'true');
    const login = await context.request.post(base + '/api/auth/login', { data: {
      login: 'henrique', password: process.env.CONTAS_TATU_TEST_PASSWORD, remember: true,
    } });
    assert.equal(login.status(), 200);
    const page = await context.newPage();
    const errors = [];
    let writes = 0;
    page.on('pageerror', error => errors.push(error.message));
    page.on('request', request => { if (request.method() !== 'GET' && request.url().includes('/api/finance')) writes++; });
    await page.clock.setFixedTime(new Date('2026-10-30T12:00:00-03:00'));
    await page.route('**/api/finance?*', route => route.fulfill({ contentType: 'application/json',
      body: JSON.stringify({ ...fixture, month: new URL(route.request().url()).searchParams.get('month') }),
    }));
    await page.goto(base);
    await page.locator('#tab-accounts').click();
    const tile = page.locator('[id^="credit-card-"]').filter({ has: page.getByRole('heading', { name: 'Cartão', exact: true }) });
    const total = await tile.locator('.card-invoice-total').innerText();
    await tile.getByRole('button', { name: 'Ver detalhes' }).click();
    const statement = page.locator('.card-details-page');
    const entries = statement.locator('.card-statement-entry');
    await entries.last().waitFor();
    assert.equal(await entries.count(), 38);
    assert.match(await statement.locator('.card-statement-summary').innerText(), /38 lançamentos/);
    assert.equal(await statement.locator('.card-statement-summary strong').innerText(), total);
    const dates = await entries.locator('td:first-child').allTextContents();
    assert.deepEqual(dates, [
      ...Array(6).fill('22/10/2026'), ...Array(5).fill('21/10/2026'), ...Array(4).fill('20/10/2026'),
      '14/10/2026', '13/10/2026', '09/10/2026', '09/10/2026', '04/10/2026', '01/10/2026',
      ...Array(17).fill('Data não informada'),
    ]);
    const big = entries.filter({ hasText: 'Big Suplementos' });
    assert.equal(await big.locator('td').first().innerText(), '22/10/2026');
    assert.equal(await big.locator('td').nth(2).innerText(), '1/2');
    const natus = entries.filter({ hasText: 'Natus Farma' }).filter({ hasText: '21/10/2026' });
    assert.equal(await natus.count(), 2);
    assert.equal(await natus.locator('td:nth-child(3)').allTextContents().then(values => values.includes('1/3')), true);
    const search = statement.getByRole('searchbox', { name: 'Buscar por descrição' });
    await search.fill('uber');
    assert.equal(await entries.count(), 8);
    assert.deepEqual(await entries.locator('td:first-child').allTextContents(), [...Array(4).fill('22/10/2026'), ...Array(4).fill('20/10/2026')]);
    assert.equal(await entries.locator('td:nth-child(3)').allTextContents().then(values => values.every(value => value === '—')), true);
    await search.fill('');
    await page.screenshot({ path: join(tmpdir(), 'contas-card-confirmed-dates.png') });
    await page.locator('#btn-next-month').click();
    await page.waitForFunction(() => document.querySelector('.card-statement-heading')?.textContent.includes('Novembro'));
    await statement.getByRole('searchbox').fill('Big Suplementos');
    assert.equal(await entries.locator('td').nth(2).innerText(), '2/2');
    assert.equal(await entries.locator('td').first().innerText(), '22/10/2026');
    await statement.getByRole('button', { name: 'Voltar para Contas' }).click();
    assert.equal(await page.locator('dialog[open], [aria-modal="true"]').count(), 0);
    assert.equal(JSON.stringify(fixture), original);
    assert.equal(writes, 0);
    assert.deepEqual(errors, []);
    console.log('PASS: all 38 imported rows, 21 confirmed dates, 17 unknown dates, descending dates, simple/installment positions, search order, global month, original date retained for future installments, unchanged totals and zero financial writes.');
  } finally { await browser.close(); }
})().catch(error => { console.error(error); process.exitCode = 1; });
